-- Article 300A for the right to property.
insert into concept_links (concept_id, source_id, chunk_id, kind)
select '00000000-0000-4000-8000-0000000c011e'::uuid, c.source_id, c.id, 'key_section'
  from chunks c join sources s on s.id = c.source_id and s.type = 'constitution' and s.status <> 'retired'
 where c.article = '300A' and c.parent_id is null
on conflict do nothing;
